def search(arr, n):
    """Write a python function to find the element that appears only once in a sorted array.

    Assumes the usual form of the problem: ``arr`` is sorted, has ``n``
    elements, every element appears exactly twice except one element that
    appears once, and that single element is returned. Returns ``-1`` when
    no such element exists (including for an empty array).
    """
    if not arr:
        return -1
    length = len(arr) if n is None else min(n, len(arr))
    if length <= 0:
        return -1
    if length == 1:
        return arr[0]

    # Binary search: pairs start at even indices before the single
    # element and at odd indices after it.
    lo, hi = 0, length - 1
    while lo < hi:
        mid = (lo + hi) // 2
        if mid % 2:
            mid -= 1
        if mid + 1 < length and arr[mid] == arr[mid + 1]:
            lo = mid + 2
        else:
            hi = mid

    if lo < length:
        candidate = arr[lo]
        if (lo == 0 or arr[lo - 1] != candidate) and (
            lo == length - 1 or arr[lo + 1] != candidate
        ):
            return candidate

    # Fallback for inputs that do not follow the exact-twice pattern:
    # count occurrences and return the first element occurring once.
    counts = {}
    for i in range(length):
        counts[arr[i]] = counts.get(arr[i], 0) + 1
    for i in range(length):
        if counts[arr[i]] == 1:
            return arr[i]
    return -1
